// Error-code (error.<CODE>) and history load-failure strings, in all 60
// locales. Backend responses carry a stable `code` (backend/src/lib/errorCodes.js);
// the app shows t('error.<CODE>') instead of the raw English message.
// Merged by add-i18n-keys.mjs, so a sync never drops or resets them.
