    "error.MEET_AUTH_UNAVAILABLE": "Google Meet యాక్సెస్ ఇంకా సెటప్ కాలేదు. మళ్లీ సైన్ ఇన్ చేయండి లేదా సెటప్ పూర్తి చేయమని మీ Workspace అడ్మిన్‌ను అడగండి.",
